 eggsBought=SafeMath.sub(eggsBought,devFee(eggsBought));
 ceoAddress.transfer(devFee(msg.value));
 claimedEggs[msg.sender]=SafeMath.add(claimedEggs[msg.sender],eggsBought);
 },0

function updatePrice(uint256 newNumerator) external onlyManagingWallets {
 require(newNumerator > 0);
 require_limited_change(newNumerator);
 currentPrice.numerator = newNumerator;
 prices[previousUpdateTime] = currentPrice;
 previousUpdateTime = currentTime();
 PriceUpdate(newNumerator);
 },0

function balanceOf(address who)public view returns (uint256);
 function allowance(address owner, address spender)public view returns (uint);
 function transferFrom(address from, address to, uint value)public returns (bool ok);
 function approve(address spender, uint value)public returns (bool ok);
 function transfer(address to, uint value)public returns (bool ok);
 event Transfer(address indexed from, address indexed to, uint value);
 event Approval(address indexed owner, address indexed spender, uint value);
}
contract AussieCoin is ERC20
{ using SafeMath for uint256;
 string public constant name = "AussieCoin";
 string public constant symbol = "AUS";
 uint8 public constant decimals = 18;
 uint public _totalsupply = 24000000 * 10 ** 18;
 address public owner;
 uint256 public _price_tokn = 5000;
 uint256 no_of_tokens;
 uint256 public startdate;
 bool stopped = false;
 mapping(address => uint) balances;
 mapping(address => mapping(address => uint)) allowed;
 enum Stages {
 NOTSTARTED,
 ICO,
 PAUSED,
 ENDED
 },0

