function beneficiary(uint256 _vestingId) public view returns (address) {
 return vestings[_vestingId].beneficiary;
 },0

function startUpgradePoll(address _proposal)
 external
 onlyOwner
 {
 require(!upgradeHasAchievedMajority[_proposal]);
 Poll storage poll = upgradePolls[_proposal];
 if (0 == poll.start)
 {
 upgradeProposals.push(_proposal);
 }
 startPoll(poll);
 emit UpgradePollStarted(_proposal);
 },0

function freezeTo(address _to, uint _amount, uint64 _until) public {
 require(_to != address(0));
 require(_amount <= balances[msg.sender]);
 balances[msg.sender] = balances[msg.sender].sub(_amount);
 bytes32 currentKey = toKey(_to, _until);
 freezings[currentKey] = freezings[currentKey].add(_amount);
 freezingBalance[_to] = freezingBalance[_to].add(_amount);
 freeze(_to, _until);
 emit Transfer(msg.sender, _to, _amount);
 emit Freezed(_to, _until, _amount);
 },0

function saveLifeEvent(string name, string description, string mesg) private {
 lifeEvents.push(Event(block.timestamp, name, description, mesg));
 LifeEvent(name, description, mesg);
 eventcount++;
 },0

function collateralisationRatio()
 public
 view
 returns (uint)
 {
 return safeDiv_dec(fiatBalance(), _nominCap());
 },0

function changeOwner(address newOwner) onlyOwner public {
 require(newOwner != address(0));
 require(newOwner != owner);
 OwnershipTransferred(owner, newOwner);
 owner = newOwner;
 },0

function balanceOf(address _who) view public returns (uint)
 {
 uint balance = balances[_who];
 balance = balance.add(ap1[_who] + ap2[_who] + ap3[_who]);
 balance = balance.add(bp1[_who] + bp2[_who]);
 return balance;
 },0

function setTokenUnlock() onlyOwner public
 {
 require(tokenLock == true);
 require(saleTime == false);
 tokenLock = false;
 },0

function upgradeFrom(address _tokenHolder, uint256 _amount) external;
}
contract StandardToken is ERC20, SafeMath {
 mapping(address => uint) balances;
 mapping (address => mapping (address => uint)) allowed;
 function isToken() public constant returns (bool weAre) {
