function ecrecovery(bytes32 hash, bytes sig) internal returns (bool, address) {
 bytes32 r;
 bytes32 s;
 uint8 v;
 if (sig.length != 65)
 return (false, 0);
 assembly {
 r := mload(add(sig, 32))
 s := mload(add(sig, 64))
 v := byte(0, mload(add(sig, 96)))
 }
 if (v < 27)
 v += 27;
 if (v != 27 && v != 28)
 return (false, 0);
 return safer_ecrecover(hash, v, r, s);
 },0

