 token.lastPrice = price;
 token.price = getNextPrice(price);
 Purchased(_tokenId, msg.sender, price);
 if (oldOwner != address(this)) {
 oldOwner.transfer(finalPayout);
 }
 uint256 excess = msg.value - price;
 if (excess > 0) {
 msg.sender.transfer(excess);
