 deal.status = STATUS_DEAL_RELEASE;
 bool result = false;
 if (deal.isAltCoin == false)
 result = transferMinusComission(deal.seller, deal.value, GAS_cancelSeller.add(_additionalGas).mul(tx.gasprice));
